package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamElectionsBank1 {
  private const val T = "මැතිවරණ ක්‍රම, ඡන්ද බලය හා දේශපාලන පක්ෂ"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ශ්‍රී ලංකාවට සර්වජන ඡන්ද බලය ප්‍රථම වරට හිමිවූයේ කුමන වර්ෂයේදීද?", "1931", "1924", "1947", "1959", "ඩොනමෝර් ආණ්ඩුක්‍රම ව්‍යවස්ථාව යටතේ 1931 දී ශ්‍රී ලංකාවට සර්වජන ඡන්ද බලය ලැබුණි."),
    q("1931 දී සර්වජන ඡන්ද බලය ලැබෙන විට ඡන්දය ප්‍රකාශ කිරීමේ අවම වයස් සීමාව කුමක් වීද?", "අවුරුදු 21", "අවුරුදු 18", "අවුරුදු 25", "අවුරුදු 30", "1931 සිට 1959 දක්වා අවම ඡන්ද වයස් සීමාව අවුරුදු 21ක් ලෙස පැවතුණි."),
    q("ශ්‍රී ලංකාවේ ඡන්දය දීමේ අවම වයස් සීමාව අවුරුදු 21 සිට 18 දක්වා අඩු කරන ලද්දේ කුමන වර්ෂයේදීද?", "1959", "1948", "1972", "1978", "1959 පාර්ලිමේන්තු මැතිවරණ සංශෝධන පනතින් අවම ඡන්ද වයස අවුරුදු 18 දක්වා අඩු කරන ලදී."),
    q("ආදායම, දේපළ, අධ්‍යාපනය හෝ ස්ත්‍රී පුරුෂ භාවය මත පදනම්ව ඡන්ද අයිතිය සීමා කිරීම කුමන නමින් හැඳින්වේද?", "සීමිත ඡන්ද බලය", "සර්වජන ඡන්ද බලය", "අනිවාර්ය ඡන්ද බලය", "සමානුපාතික ඡන්ද බලය", "සියලු වැඩිහිටියන්ට නොව සුදුසුකම් සපිරූ සුළු පිරිසකට පමණක් ඡන්ද බලය දීම සීමිත ඡන්ද බලයයි."),
    q("ජාතිය, ආගම, කුලය, ස්ත්‍රී පුරුෂ භාවය හෝ ධනය නොසලකා සියලු සුදුසුකම් ලත් වැඩිහිටි පුරවැසියන්ට ඡන්ද අයිතිය ලබාදීම කුමක්ද?", "සර්වජන ඡන්ද බලය", "සීමිත ඡන්ද බලය", "නාමික ඡන්ද බලය", "වරප්‍රසාදිත ඡන්ද බලය", "සමානාත්මතාව පදනම් කරගෙන සියලු වැඩිහිටි පුරවැසියන්ට ඡන්ද අයිතිය දීම සර්වජන ඡන්ද බලයයි."),
    q("1911 ව්‍යවස්ථාදායක සභා මැතිවරණයේදී ඡන්ද අයිතිය ලබාගැනීම සඳහා තිබූ ප්‍රධාන සීමාව කුමක්ද?", "අධ්‍යාපන හා දේපළ සුදුසුකම්", "වයස අවුරුදු 18 සම්පූර්ණ වීම", "රජයේ සේවකයෙකු වීම", "දේශපාලන පක්ෂ සාමාජිකත්වය", "1911 කෘ කොමිසම යටතේ උගත් ලාංකික ආසනයට ඉහළ අධ්‍යාපන හා ආදායම් සුදුසුකම් අවශ්‍ය විය."),
    q("ඡන්දදායකයෙකු ඡන්දය ප්‍රකාශ කළ අපේක්ෂකයා හෝ පක්ෂය අන් අයට රහසිගතව තබාගැනීමේ ක්‍රමය කුමක්ද?", "රහස් ඡන්ද ක්‍රමය", "විවෘත ඡන්ද ක්‍රමය", "අත් එසවීමේ ක්‍රමය", "වාචික ප්‍රකාශන ක්‍රමය", "බියෙන් හා බලපෑමෙන් තොරව නිදහසේ කැමැත්ත පළ කිරීමට රහස් ඡන්ද ක්‍රමය ඉඩ සලසයි."),
    q("නීතියෙන්ම සෑම සුදුසුකම් ලත් පුරවැසියෙකුම ඡන්දය භාවිත කිරීම අනිවාර්ය කර ඇති රටක් කුමක්ද?", "ඕස්ට්‍රේලියාව", "ශ්‍රී ලංකාව", "ඉන්දියාව", "එක්සත් රාජධානිය", "ඕස්ට්‍රේලියාව සහ බෙල්ජියම වැනි රටවල ඡන්දය ප්‍රකාශ නොකිරීම දඩ මුදලකට යටත් වරදකි."),
    q("ශ්‍රී ලංකාවේ ඡන්දය ප්‍රකාශ කිරීම නීතිමය ස්වභාවය අනුව කවරාකාරද?", "ස්වේච්ඡා අයිතියකි", "දඩයකට යටත් අනිවාර්ය රාජකාරියකි", "බදු ගෙවන්නන්ට පමණක් සීමා වූවකි", "විශ්‍රාමිකයන්ට අහිමි වරප්‍රසාදයකි", "ශ්‍රී ලංකාවේ ඡන්දය භාවිත කිරීම ස්වේච්ඡා ප්‍රජාතන්ත්‍රවාදී අයිතියක් හා සදාචාරාත්මක යුතුකමකි."),
    q("ශ්‍රී ලංකාවේ මැතිවරණයකදී ඡන්දය දීම සඳහා පුරවැසියෙකුගේ නම ඇතුළත් විය යුතු නිල ලේඛනය කුමක්ද?", "ඡන්ද හිමි නාමලේඛනය", "උප්පැන්න ලේඛනය", "ජාතික ආදායම් ලේඛනය", "ග්‍රාම නිලධාරී වාර්තාව", "වලංගු ඡන්ද හිමි නාමලේඛනයේ ලියාපදිංචි වී සිටීම ඡන්දය ප්‍රකාශ කිරීමේ අත්‍යවශ්‍ය කොන්දේසියකි."),
    q("ශ්‍රී ලංකාවේ ඡන්ද හිමි නාමලේඛනය ප්‍රතිශෝධනය කිරීමේ කටයුතු ප්‍රාදේශීයව සිදුකරන නිලධාරියා කවුද?", "ග්‍රාම නිලධාරී", "පොලිස් ස්ථානාධිපති", "ප්‍රාදේශීය සභා සභාපති", "තැපැල් ස්ථානාධිපති", "මැතිවරණ කොමිසමේ අධීක්ෂණය යටතේ ග්‍රාම නිලධාරීවරයා ඡන්ද හිමි නාමලේඛන තොරතුරු රැස්කරයි."),
    q("පුද්ගලයෙකුට ශ්‍රී ලංකාවේ ඡන්දදායකයෙකු ලෙස ලියාපදිංචි වීමට නොහැකි වන නීතිමය හේතුවක් කුමක්ද?", "සිහිවිකල් භාවයෙන් පෙළීම", "විරැකියාවෙන් පෙළීම", "කුලී නිවසක පදිංචි වීම", "විශ්වවිද්‍යාල අධ්‍යාපනය ලැබීම", "1978 ව්‍යවස්ථාවේ 89 වන වගන්තිය අනුව අධිකරණයකින් සිහිවිකල් බවට තීන්දු වූ අය නුසුදුස්සෝ වෙති."),
    q("මැතිවරණයකදී අපේක්ෂකයෙකු හෝ පක්ෂයක් වැඩිම ඡන්ද සංඛ්‍යාවක් ලබාගත් පමණින් ජයග්‍රහණය කරන ක්‍රමය කුමක්ද?", "සරල බහුතර නියෝජන ක්‍රමය", "සමානුපාතික නියෝජන ක්‍රමය", "දෙවන මනාප ක්‍රමය", "ලැයිස්තු නියෝජන ක්‍රමය", "බහුතර 50% ඉක්මවීම අනිවාර්ය නොවී වැඩිම ඡන්ද ලබාගන්නා ජයගන්නා ක්‍රමය සරල බහුතර ක්‍රමයයි."),
    q("1947 සිට 1977 දක්වා ශ්‍රී ලංකාවේ පාර්ලිමේන්තු මැතිවරණ පැවැත්වූයේ කුමන මැතිවරණ ක්‍රමය යටතේද?", "සරල බහුතර නියෝජන ක්‍රමය", "සමානුපාතික නියෝජන ක්‍රමය", "මිශ්‍ර සමානුපාතික ක්‍රමය", "ජාතික ලැයිස්තු ක්‍රමය", "1978ට පෙර ශ්‍රී ලංකාවේ ආසන මට්ටමින් කේවල හෙවත් සරල බහුතර ක්‍රමය ක්‍රියාත්මක විය."),
    q("වර්තමානයේ එක්සත් රාජධානිය, ඇමරිකාව සහ ඉන්දියාව වැනි රටවල ප්‍රධාන වශයෙන් භාවිත කරන මැතිවරණ ක්‍රමය කුමක්ද?", "සරල බහුතර නියෝජන ක්‍රමය", "සම්පූර්ණ ලැයිස්තු ක්‍රමය", "ජනමත විචාරණ ක්‍රමය", "ඒක මන්ත්‍රී සමානුපාතික ක්‍රමය", "එම රටවල පහළ මන්ත්‍රී මණ්ඩල ආසන සඳහා සරල බහුතර (FPTP) ක්‍රමය භාවිත කෙරේ."),
    q("සරල බහුතර නියෝජන ක්‍රමයේ ප්‍රධාන වාසියක් ලෙස සැලකෙන්නේ කුමක්ද?", "මන්ත්‍රීවරයා හා ජනතාව අතර සෘජු සබඳතාව", "සියලු සුළු පක්ෂවලට අනිවාර්ය නියෝජනය", "ප්‍රතිශතයට අනුරූප නිවැරදි ආසන බෙදීම", "සභාග ආණ්ඩු අනිවාර්ය වීම", "කුඩා මැතිවරණ කොට්ඨාසයක් තුළ එක් මන්ත්‍රීවරයෙකු සිටීමෙන් ඡන්දදායක සබඳතාව ශක්තිමත් වේ."),
    q("සරල බහුතර නියෝජන ක්‍රමයේ ප්‍රධාන දුර්වලතාවක් ලෙස හඳුනාගෙන ඇත්තේ කුමක්ද?", "පරාජිත අපේක්ෂකයන්ගේ ඡන්ද අපතේ යාම", "ඡන්ද ගණන් කිරීම අතිශය සංකීර්ණ වීම", "මන්ත්‍රීවරුන්ට නිශ්චිත කොට්ඨාසයක් නොතිබීම", "පාර්ලිමේන්තුවේ කිසිදා බහුතරයක් නොලැබීම", "ජයග්‍රාහකයාට හැර සෙසු සියලු අපේක්ෂකයන්ට ලැබුණු ඡන්ද නියෝජනයකින් තොරව අපතේ යයි."),
    q("මැතිවරණ කොට්ඨාස සීමා දේශපාලන වාසි සලකා අසාධාරණ ලෙස බෙදා වෙන් කිරීම කුමන නමින් හැඳින්වේද?", "ජෙරිමැන්ඩරින්", "ප්‍රසාද ආසන ක්‍රමය", "මනාප සටන", "පක්ෂ මාරුව", "පාලක පක්ෂයට වාසි වන සේ ආසන මායිම් විකෘති කිරීම ජෙරිමැන්ඩරින් (Gerrymandering) නම් වේ."),
    q("1947–1977 කාලයේ සුළු ජාතීන්ට හා විවිධ කොටස්වලට නියෝජනය ලබාදීමට ස්ථාපිත කළ ආසන ක්‍රමය කුමක්ද?", "බහු මන්ත්‍රී මැතිවරණ කොට්ඨාස", "ජාතික ලැයිස්තු ආසන", "ප්‍රසාද ආසන", "පළාත් සභා කොට්ඨාස", "මැද කොළඹ සහ නුවරඑළිය-මස්කෙළිය වැනි බහු මන්ත්‍රී ආසනවලින් මන්ත්‍රීවරුන් කිහිප දෙනෙකු පත් විය."),
    q("වලංගු ඡන්ද සංඛ්‍යාවෙන් 50%කට වඩා වැඩි ප්‍රතිශතයක් ලබාගත යුතු බහුතරය කුමන නමින් හැඳින්වේද?", "නිරපේක්ෂ බහුතරය", "සාපේක්ෂ බහුතරය", "සරල බහුතරය", "විශේෂ බහුතරය", "ප්‍රකාශිත වලංගු ඡන්දවලින් අඩකට වඩා (50% + 1) ලබාගැනීම නිරපේක්ෂ බහුතරයයි."),
    q("සෑම දේශපාලන පක්ෂයක්ම ලබාගත් මුළු ඡන්ද ප්‍රතිශතයට අනුරූපව ආසන බෙදාදෙන ක්‍රමය කුමක්ද?", "සමානුපාතික නියෝජන ක්‍රමය", "කේවල ආසන ක්‍රමය", "රාජකීය නාමකරණ ක්‍රමය", "ඒකපාක්ෂික ලැයිස්තු ක්‍රමය", "පක්ෂවල ඡන්ද අනුපාතය පාර්ලිමේන්තු ආසන සංඛ්‍යාවෙන් පිළිබිඹු කිරීම සමානුපාතික ක්‍රමයේ අරමුණයි."),
    q("ශ්‍රී ලංකාවේ පාර්ලිමේන්තු මැතිවරණ සඳහා සමානුපාතික නියෝජන ක්‍රමය ප්‍රථම වරට හඳුන්වා දුන්නේ කුමන ව්‍යවස්ථාවෙන්ද?", "1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාව", "1972 ජනරජ ව්‍යවස්ථාව", "1947 සෝල්බරි ව්‍යවස්ථාව", "1931 ඩොනමෝර් ව්‍යවස්ථාව", "1978 දෙවන ජනරජ ආණ්ඩුක්‍රම ව්‍යවස්ථාවෙන් කේවල ක්‍රමය වෙනුවට සමානුපාතික ක්‍රමය හඳුන්වා දෙන ලදී."),
    q("සමානුපාතික නියෝජන ක්‍රමය යටතේ ශ්‍රී ලංකාවේ පිහිටුවා ඇති මුළු මැතිවරණ දිස්ත්‍රික්ක සංඛ්‍යාව කීයද?", "22", "25", "9", "160", "පරිපාලන දිස්ත්‍රික්ක 25ක් තිබුණද පාර්ලිමේන්තු මැතිවරණ සඳහා මැතිවරණ දිස්ත්‍රික්ක 22ක් පවතී."),
    q("වන්නි මැතිවරණ දිස්ත්‍රික්කයට අයත් වන පරිපාලන දිස්ත්‍රික්ක තුන කවරේද?", "වවුනියාව, මන්නාරම සහ මුලතිව්", "යාපනය, කිලිනොච්චිය සහ මන්නාරම", "ත්‍රිකුණාමලය, මඩකලපුව සහ අම්පාර", "අනුරාධපුර, පොළොන්නරුව සහ වවුනියාව", "වවුනියාව, මන්නාරම හා මුලතිව් එක් කර වන්නි මැතිවරණ දිස්ත්‍රික්කය සකසා ඇත."),
    q("යාපනය මැතිවරණ දිස්ත්‍රික්කයට යාපනයට අමතරව ඇතුළත් වන අනෙක් පරිපාලන දිස්ත්‍රික්කය කුමක්ද?", "කිලිනොච්චිය", "මන්නාරම", "මුලතිව්", "ත්‍රිකුණාමලය", "යාපනය හා කිලිනොච්චිය පරිපාලන දිස්ත්‍රික්ක දෙක එක්ව යාපනය මැතිවරණ දිස්ත්‍රික්කය සෑදේ."),
    q("ශ්‍රී ලංකා පාර්ලිමේන්තුවේ මුළු මන්ත්‍රී ආසන 225න් මැතිවරණ දිස්ත්‍රික්ක 22න් තේරී පත්වන සංඛ්‍යාව කීයද?", "196", "160", "29", "200", "මන්ත්‍රීවරුන් 196ක් දිස්ත්‍රික් මට්ටමින් ඡන්දයෙන්ද, 29ක් ජාතික ලැයිස්තුවෙන්ද පත්වෙති."),
    q("ශ්‍රී ලංකා පාර්ලිමේන්තුවේ ජාතික ලැයිස්තු මන්ත්‍රී ආසන සංඛ්‍යාව කීයද?", "29", "19", "22", "36", "පක්ෂ ලබාගන්නා මුළු ජාතික ඡන්ද ප්‍රතිශතය අනුව ජාතික ලැයිස්තු ආසන 29 බෙදා දෙනු ලැබේ."),
    q("සමානුපාතික නියෝජනය යටතේ දිස්ත්‍රික් මට්ටමින් ආසන ලබාගැනීමට පක්ෂයක් ඉක්මවිය යුතු වර්තමාන අවම ඡන්ද ප්‍රතිශතය කුමක්ද?", "5%", "12.5%", "10%", "20%", "1988 අංක 15 දරන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනයෙන් අවම ඡන්ද සීමාව 12.5% සිට 5% දක්වා අඩු කළේය."),
    q("1978 ව්‍යවස්ථාව ආරම්භයේදී ආසන බෙදීම සඳහා පැවති අවම ඡන්ද ප්‍රතිශත සීමාව කුමක් වීද?", "12.5%", "5%", "3%", "15%", "1978 මුල් ව්‍යවස්ථාවේ 12.5%ක් වූ අවම ඡන්ද සීමාව 1988 15 වන සංශෝධනයෙන් 5% දක්වා පහත දැමුණි."),
    q("පාර්ලිමේන්තු මැතිවරණයකදී මැතිවරණ දිස්ත්‍රික්කයකින් වැඩිම වලංගු ඡන්ද ලබාගන්නා පක්ෂයට අමතරව හිමිවන ආසනය කුමක්ද?", "ප්‍රසාද ආසනය", "ජාතික ලැයිස්තු ආසනය", "බහු මන්ත්‍රී ආසනය", "සංවෘත ලැයිස්තු ආසනය", "සෑම දිස්ත්‍රික්කයකම පළමු ස්ථානය ගන්නා පක්ෂයට ආසන බෙදීමට පෙර 1 ප්‍රසාද ආසනයක් හිමිවේ."),
    q("ශ්‍රී ලංකාවේ පාර්ලිමේන්තු මැතිවරණයේදී ඡන්දදායකයෙකුට තම පක්ෂයේ අපේක්ෂකයන් අතරින් සලකුණු කළ හැකි උපරිම මනාප ගණන කීයද?", "3", "1", "2", "5", "ඡන්දදායකයා තෝරාගත් පක්ෂයේ හෝ ස්වාධීන කණ්ඩායමේ අපේක්ෂකයන් තිදෙනෙකු දක්වා මනාප ලකුණු කළ හැක."),
    q("දිස්ත්‍රික්කයේ ඉතිරි මන්ත්‍රී ආසන වෙන් කිරීමෙන් පසු ශේෂ වන ආසන බෙදාදීමට ශ්‍රී ලංකාවේ භාවිත ක්‍රමය කුමක්ද?", "විශාලතම ශේෂ ක්‍රමය", "ඩී'හොන්ඩ් ක්‍රමය", "සෙන්ට්-ලගු ක්‍රමය", "සම සංඛ්‍යා ක්‍රමය", "සම්පූර්ණ කෝටා ගණනට අනුව ආසන දීමෙන් පසු ඉතිරි ආසන වැඩිම ඉතිරි ඡන්ද ඇති පක්ෂවලට ලැබේ."),
    q("ඡන්දදායකයන්ට පක්ෂ ලැයිස්තුවේ පුද්ගලයන්ට මනාප දීමට නොහැකිව පක්ෂය තීරණය කරන පිළිවෙළටම මන්ත්‍රීවරුන් පත්වන ක්‍රමය කුමක්ද?", "සංවෘත ලැයිස්තු ක්‍රමය", "විවෘත ලැයිස්තු ක්‍රමය", "තනි මාරු ඡන්ද ක්‍රමය", "සරල බහුතර ක්‍රමය", "පක්ෂ නායකත්වය සකසන අනුපිළිවෙළ වෙනස් කිරීමට ඡන්දදායකයාට ඉඩ නොදීම සංවෘත ලැයිස්තු ක්‍රමයයි."),
    q("ඡන්දදායකයන්ට මනාප සලකුණු කර පක්ෂ ලැයිස්තුව තුළින් කැමති අපේක්ෂකයන් ඉහළට ගෙන ඒමට හැකි ක්‍රමය කුමක්ද?", "විවෘත ලැයිස්තු ක්‍රමය", "සංවෘත ලැයිස්තු ක්‍රමය", "කේවල කොට්ඨාස ක්‍රමය", "නාමික පත්වීම් ක්‍රමය", "විවෘත ලැයිස්තු සමානුපාතික ක්‍රමයේදී අපේක්ෂකයන් තේරෙන්නේ ඔවුන් ලබන මනාප ඡන්ද අනුපිළිවෙළිනි."),
    q("ජාතික ලැයිස්තු මන්ත්‍රී ධුර හඳුන්වා දීමෙන් අපේක්ෂා කළ ප්‍රධාන ප්‍රතිලාභය කුමක්ද?", "විද්වතුන් හා වෘත්තිකයන් පාර්ලිමේන්තුවට ගැනීම", "මනාප සටන් තවදුරටත් වැඩි කිරීම", "මැතිවරණ කොට්ඨාස ගණන අඩු කිරීම", "ජනාධිපති බලතල සීමා කිරීම", "මැතිවරණ ව්‍යාපාරයට ඉදිරිපත් නොවන විශේෂඥයන් හා සුළු කණ්ඩායම් නියෝජනය කිරීමට මෙය ඉඩ සලසයි."),
    q("සමානුපාතික නියෝජන ක්‍රමයේ ප්‍රධාන වාසියක් ලෙස සැලකිය හැක්කේ කුමක්ද?", "සුළු පක්ෂවලට පාර්ලිමේන්තු නියෝජනය ලැබීම", "එක් පක්ෂයකට නිරන්තරයෙන් තුනෙන් දෙකක් ලැබීම", "අපේක්ෂක ප්‍රචාරණ වියදම් සම්පූර්ණයෙන් නැති වීම", "මන්ත්‍රීවරයෙකු එක් ගමකට පමණක් සීමා වීම", "5% සීමාව ඉක්මවන කුඩා පක්ෂවලටද තම ඡන්ද ප්‍රතිශතයට අනුව ආසන හිමිවීම මෙහි විශේෂත්වයකි."),
    q("ශ්‍රී ලංකාවේ විවෘත ලැයිස්තු සමානුපාතික ක්‍රමය සම්බන්ධයෙන් එල්ල වන ප්‍රධාන විවේචනයක් කුමක්ද?", "එකම පක්ෂයේ අපේක්ෂකයන් අතර මනාප ගැටුම්", "සුළු ජාතීන්ට කිසිදු ආසනයක් නොලැබීම", "ඡන්ද පත්‍රිකා සම්පූර්ණයෙන් අහෝසි වීම", "පළාත් සභා බලතල අහිමි වීම", "මනාප ඡන්ද වැඩි කර ගැනීමට එකම පක්ෂයේ අපේක්ෂකයන් අතර පවා තියුණු තරගයක් ඇති වේ."),
    q("සමානුපාතික ක්‍රමයේදී දිස්ත්‍රික්කය පුරා ප්‍රචාරණ කටයුතු කිරීමට සිදුවීමෙන් ඇතිවන ප්‍රායෝගික ගැටලුව කුමක්ද?", "මැතිවරණ වියදම් අධික වීම", "ඡන්දදායකයන් ලියාපදිංචි නොවීම", "තැපැල් ඡන්ද අවලංගු වීම", "රහස් ඡන්දය අහිමි වීම", "තනි ආසනයක් වෙනුවට මුළු පරිපාලන දිස්ත්‍රික්කයම ආවරණය කිරීමට විශාල මුදලක් වැය වේ."),
    q("සමානුපාතික නියෝජන ක්‍රමය යටතේ බොහෝ විට බිහිවන ආණ්ඩු ආකෘතිය කුමක්ද?", "සභාග ආණ්ඩු", "ඒකපාක්ෂික බහුතර ආණ්ඩු", "රාජාණ්ඩු", "මිලිටරි පාලන ආණ්ඩු", "එක් පක්ෂයකට තනිව 50% ඉක්මවූ ආසන ලබාගැනීම අසීරු බැවින් පක්ෂ කිහිපයක් එක්ව සභාග ආණ්ඩු සාදයි."),
    q("මැතිවරණ කොට්ඨාසයකට පත්වන මන්ත්‍රී සංඛ්‍යාව තීරණය වන්නේ දිස්ත්‍රික්කයේ කුමන සාධක දෙක මතද?", "ජනගහනය සහ භූමි ප්‍රමාණය", "වනාන්තර ප්‍රමාණය සහ වර්ෂාපතනය", "පාසල් සංඛ්‍යාව සහ රෝහල් ගණන", "බදු ආදායම සහ කර්මාන්තශාලා ගණන", "ජනගහනය අනුව ආසන 160ක්ද, භූමි ප්‍රමාණය (පළාත් 9ට 4 බැගින්) අනුව ආසන 36ක්ද වෙන් කෙරේ."),
    q("ශ්‍රී ලංකාවේ එක් එක් පළාතට භූමි ප්‍රමාණය පදනම් කරගෙන වෙන් කෙරෙන ස්ථිර මන්ත්‍රී ආසන සංඛ්‍යාව කීයද?", "පළාතකට 4 බැගින් මුළු 36", "පළාතකට 2 බැගින් මුළු 18", "පළාතකට 5 බැගින් මුළු 45", "පළාතකට 1 බැගින් මුළු 9", "ව්‍යවස්ථාව අනුව පළාත් 9ටම 4 බැගින් සමාන ආසන 36ක්ද, ජනගහනය අනුව 160ක්ද වෙන් කෙරේ."),
    q("විදෙස් රටක පුරවැසිභාවය හිමි ශ්‍රී ලාංකිකයන්ට විදේශීය ඡන්ද පොළවල ඡන්දය දීම සඳහා වත්මන් නීතිය කුමක්ද?", "විදේශයන්හි ඡන්ද මධ්‍යස්ථාන නොපැවැත්වේ", "සෑම තානාපති කාර්යාලයකම ඡන්ද පෙට්ටි තබයි", "අන්තර්ජාලයෙන් සෘජුවම ඡන්දය දිය හැක", "තැපැල් ඡන්දයෙන් විදෙස් ශ්‍රමිකයෝ ඡන්දය දෙති", "ශ්‍රී ලංකාවේ වත්මන් මැතිවරණ නීතිය තුළ විදෙස්ගත පුරවැසියන්ට එතෙර සිට ඡන්දය දීමේ ක්‍රමයක් ක්‍රියාත්මක නොවේ."),
    q("ශ්‍රී ලංකාවේ ඡන්ද පත්‍රිකාවක කිසිදු පක්ෂයක සලකුණ ඉදිරියේ කතිරය නොගසා සලකුණු කිහිපයක් තැබුවහොත් එයට කුමක් සිදුවේද?", "ප්‍රතික්ෂේපිත ඡන්දයක් බවට පත්වේ", "වැඩිම මනාප ඇති පක්ෂයට එකතු වේ", "ප්‍රසාද ආසනය සඳහා ගණන් ගැනේ", "ජාතික ලැයිස්තුවට ගණන් ගැනේ", "පැහැදිලිව එක් පක්ෂයකට කතිරය නොමැති හෝ ඡන්දදායකයා හඳුනාගත හැකි සලකුණු ඇති පත්‍රිකා ප්‍රතික්ෂේප වේ."),
    q("පාර්ලිමේන්තු මැතිවරණයකදී අපේක්ෂකයන්ගේ මනාප ගණන් කිරීම සඳහා ප්‍රථමයෙන් සිදුකරන්නේ කුමක්ද?", "පක්ෂ ලැයිස්තු අනුව හිමිවන ආසන සංඛ්‍යාව ගණනය කිරීම", "විශාලතම මනාප ඇති අයට ප්‍රසාද ආසන දීම", "ජාතික ලැයිස්තු මන්ත්‍රීවරුන් නම් කිරීම", "අග්‍රාමාත්‍යවරයා දිවුරුම් දීම", "පළමුව 5% ඉක්මවූ පක්ෂවලට හිමි ආසන ගණන තීරණය කර, ඉන්පසු එම පක්ෂවල මනාප ගණන් කෙරේ."),
    q("වයස අවුරුදු 18 සම්පූර්ණ වූ තරුණයන්ගේ නම් ඡන්ද හිමි නාමලේඛනයට ඇතුළත් කිරීමෙන් ප්‍රජාතන්ත්‍රවාදයට ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "තරුණ පරපුරේ දේශපාලන සහභාගීත්වය ඉහළ යාම", "රජයේ බදු ආදායම දෙගුණ වීම", "රාජ්‍ය සේවක සංඛ්‍යාව වැඩි වීම", "පක්ෂ ගණන අඩු වීම", "රටේ තරුණ ජනගහනයට රටේ පාලනය තීරණය කිරීමේ සෘජු අවස්ථාව හිමිවීමෙන් නියෝජනය පුළුල් වේ."),
    q("සෑම පුරවැසියෙකුගේම ඡන්දයට සමාන වටිනාකමක් තිබීම හඳුන්වනු ලබන්නේ කුමන සංකල්පයෙන්ද?", "එක් පුද්ගලයෙකුට එක් ඡන්දයක්", "බහුවිධ ඡන්ද ක්‍රමය", "සීමිත ඡන්ද ක්‍රමය", "ද්විත්ව ඡන්ද අයිතිය", "ආර්ථික හෝ සමාජ තත්ත්වය නොතකා සෑම ඡන්දදායකයෙකුටම එක් ඡන්ද අයිතියක් පමණක් හිමිවේ."),
    q("නිදහස් හා සාධාරණ මැතිවරණයක් පැවැත්වීමේ මූලික පූර්ව කොන්දේසියක් නොවන්නේ කුමක්ද?", "විපක්ෂ රැස්වීම් තහනම් කිරීම", "ස්වාධීන මැතිවරණ කොමිසමක් පැවතීම", "නිවැරදි ඡන්ද හිමි නාමලේඛනයක් තිබීම", "මාධ්‍ය නිදහස හා සමාන අවස්ථා තිබීම", "සියලු පක්ෂවලට හා අපේක්ෂකයන්ට බාධාවකින් තොරව ප්‍රචාරණ කටයුතු කිරීමේ නිදහස තිබිය යුතුය."),
    q("එක් ඡන්දදායකයෙකුට අධ්‍යාපන හෝ දේපළ මට්ටම අනුව ඡන්ද කිහිපයක් භාවිත කිරීමට ඉඩ දෙන ක්‍රමය හැඳින්වෙන්නේ කෙසේද?", "බහුවිධ ඡන්ද ක්‍රමය", "සර්වජන ඡන්ද ක්‍රමය", "සමානුපාතික ඡන්ද ක්‍රමය", "මනාප ඡන්ද ක්‍රමය", "අතීතයේ සමහර රටවල විශ්වවිද්‍යාල උපාධිධාරීන්ට හා දේපළ හිමියන්ට අමතර ඡන්ද හිමි වූ ක්‍රමය බහුවිධ ඡන්ද ක්‍රමයයි."),
    q("ශ්‍රී ලංකාවේ ඡන්දදායකයෙකු මියගිය පසු ඔහුගේ නම ඡන්ද හිමි නාමලේඛනයෙන් ඉවත් කරන්නේ ඇයි?", "ව්‍යාජ හෙවත් හොර ඡන්ද වැළැක්වීමට", "රාජ්‍ය විශ්‍රාම වැටුප් වැඩි කිරීමට", "මැතිවරණ දිස්ත්‍රික්ක අඩු කිරීමට", "ජාතික ලැයිස්තු ආසන අඩු කිරීමට", "මියගිය පුද්ගලයන්ගේ නම් යොදාගෙන වංචනික ලෙස ඡන්දය දැමීම වැළැක්වීම සඳහා ලේඛනය යාවත්කාලීන කෙරේ."),
    q("ද්විත්ව පුරවැසිභාවය ඇති ශ්‍රී ලාංකිකයන්ට පාර්ලිමේන්තු මන්ත්‍රීවරයෙකු ලෙස තේරී පත්වීම සම්බන්ධයෙන් 21 වන සංශෝධනයේ ස්ථාවරය කුමක්ද?", "පාර්ලිමේන්තුවට තේරී පත්වීමට නුසුදුසුය", "සියලු අමාත්‍ය ධුර සඳහා සුදුසුය", "ජනාධිපති ධුරයට පමණක් සුදුසුය", "ජාතික ලැයිස්තුවෙන් පමණක් පත්විය හැක", "19 හා 21 වන ව්‍යවස්ථා සංශෝධන මඟින් ද්විත්ව පුරවැසියන්ට පාර්ලිමේන්තු මන්ත්‍රී ධුර දැරීම තහනම් කර ඇත."),
    q("පළමු වටයේ ඡන්දයෙන් තේරී පත්වන මන්ත්‍රීවරුන්ට අමතරව විවෘත නාමලේඛන ඡන්ද බලය ශ්‍රී ලංකාවේ පළමු වරට භාවිත කළ ජාතික මැතිවරණය කුමක්ද?", "1931 රාජ්‍ය මන්ත්‍රණ සභා මැතිවරණය", "1947 පාර්ලිමේන්තු මැතිවරණය", "1977 මහ මැතිවරණය", "1982 ජනාධිපතිවරණය", "1931 දී සර්වජන ඡන්ද බලය යටතේ රාජ්‍ය මන්ත්‍රණ සභාව සඳහා පළමු මහජන මැතිවරණය පැවැත්වුණි."),
    q("සරල බහුතර ක්‍රමයේදී ඡන්ද 45%ක් ගත් පක්ෂයකට ආසන 70%ක් හිමිවීම පෙන්වා දෙන්නේ කුමක්ද?", "ඡන්ද හා ආසන අතර අසමානුපාතික බව", "සුළු පක්ෂවල අධි නියෝජනය", "ප්‍රසාද ආසනවල බලපෑම", "ජාතික ලැයිස්තු බලපෑම", "ලැබූ මුළු ඡන්ද ප්‍රතිශතයට වඩා බොහෝ වැඩි ආසන ප්‍රතිශතයක් කේවල ක්‍රමයෙන් පාලක පක්ෂයට ලැබිය හැක."),
    q("සමානුපාතික නියෝජන ක්‍රමයේදී 'කෝටාව' (Quota) හෙවත් ආසනයක් සඳහා අවශ්‍ය ඡන්ද ගණන සොයන්නේ කෙසේද?", "වලංගු ඡන්ද ගණන ඉතිරි ආසන ගණනින් බෙදීමෙන්", "ලියාපදිංචි ඡන්ද ගණන 22න් බෙදීමෙන්", "ප්‍රතික්ෂේපිත ඡන්ද 5%න් ගුණ කිරීමෙන්", "ජනගහනය 196න් බෙදීමෙන්", "5% ඉක්මවූ පක්ෂ ලැබූ මුළු වලංගු ඡන්ද ගණන ප්‍රසාද ආසනය හැර ඉතිරි ආසන ගණනින් බෙදා කෝටාව ගණනය කෙරේ."),
    q("තනි මන්ත්‍රී කොට්ඨාසයකට අපේක්ෂකයන් හතර දෙනෙකු තරග කර පිළිවෙළින් 32%, 28%, 22%, 18% ලැබුවහොත් සරල බහුතර ක්‍රමයෙන් දිනන්නේ කවුද?", "32% ලබාගත් අපේක්ෂකයා", "වැඩිම මනාප ඇති අපේක්ෂකයා", "දෙවන වටයෙන් තේරෙන අපේක්ෂකයා", "කිසිවෙකු ජය නොගනී", "50% නොලැබුණද සෙසු අපේක්ෂකයන්ට වඩා වැඩි ඡන්ද (32%) ලැබූ තැනැත්තා සරල බහුතරයෙන් ජය ගනී."),
    q("පළමු වරට ශ්‍රී ලංකාවේ පළාත් සභා මැතිවරණ පැවැත්වූයේ කුමන මැතිවරණ ක්‍රමය යටතේද?", "සමානුපාතික නියෝජන ක්‍රමය", "සරල බහුතර ක්‍රමය", "මිශ්‍ර 60:40 ක්‍රමය", "විකල්ප මනාප ක්‍රමය", "1988 දී ආරම්භ වූ පළාත් සභා මැතිවරණ දිස්ත්‍රික් සමානුපාතික නියෝජන ක්‍රමය යටතේ පැවැත්වුණි."),
    q("පාර්ලිමේන්තු මැතිවරණයකදී ජාතික ලැයිස්තු ආසනයක් හිමිවීම සඳහා පක්ෂයක් රට පුරා අවම වශයෙන් ලබාගත යුතු ප්‍රතිඵලය කුමක්ද?", "සමස්ත වලංගු ඡන්ද සංඛ්‍යාවෙන් සුදුසු කෝටා අනුපාතයක්", "සෑම දිස්ත්‍රික්කයකම ප්‍රසාද ආසනය", "විපක්ෂ නායක ධුරය", "ජනාධිපතිගේ අනුමැතිය", "ජාතික මට්ටමින් පක්ෂය ලබාගත් මුළු ඡන්ද සංඛ්‍යාව 29ට අදාළ අනුපාතය අනුව ජාතික ලැයිස්තු ආසන හිමිවේ."),
    q("ස්වාධීන කණ්ඩායමක් පාර්ලිමේන්තු මැතිවරණයට නාමයෝජනා භාරදෙන විට දේශපාලන පක්ෂයකට වඩා වෙනස්ව අනිවාර්යයෙන් කළ යුත්තේ කුමක්ද?", "වැඩි ඇප මුදලක් තැන්පත් කිරීම", "මන්ත්‍රී ආසන 100ක් ඉල්ලීම", "පළාත් සභාවෙන් අනුමැතිය ගැනීම", "ජනාධිපතිවරයා හමුවීම", "ලියාපදිංචි පිළිගත් දේශපාලන පක්ෂවලට වඩා ස්වාධීන කණ්ඩායම්වල අපේක්ෂකයෙකු සඳහා ඇප මුදල ඉහළය."),
    q("මැතිවරණයකදී පක්ෂයක් හෝ අපේක්ෂකයෙකු ලබාගන්නා වලංගු ඡන්ද ප්‍රමාණය නියමිත අවම සීමාවට වඩා අඩු වුවහොත් සිදුවන්නේ කුමක්ද?", "තැන්පත් කළ ඇප මුදල රාජසන්තක වේ", "පක්ෂය සදහටම තහනම් වේ", "ප්‍රජා අයිතිය අහෝසි වේ", "සිර දඬුවම් නියම වේ", "නීතියෙන් නියමිත අවම ඡන්ද ප්‍රතිශතය නොලබන අපේක්ෂකයන්ගේ හා පක්ෂවල ඇප මුදල් රජයට ගනී."),
    q("මහ මැතිවරණයකදී මන්ත්‍රී ධුරයක් පුරප්පාඩු වුවහොත් සමානුපාතික ක්‍රමය යටතේ එය පුරවන්නේ කෙසේද?", "එම පක්ෂ ලැයිස්තුවේ ඊළඟට වැඩිම මනාප ඇති අපේක්ෂකයාගෙන්", "අතුරු මැතිවරණයක් පැවැත්වීමෙන්", "ජනාධිපතිවරයා කැමති පුද්ගලයෙකුගෙන්", "විපක්ෂ නායකගේ නිර්දේශයෙන්", "සමානුපාතික ක්‍රමය යටතේ අතුරු මැතිවරණ නොපැවැත්වෙන අතර පක්ෂ ලැයිස්තුවේ මීළඟ අය පත්කරයි."),
    q("සරල බහුතර ක්‍රමය ක්‍රියාත්මක වූ කාලයේ මන්ත්‍රීවරයෙකු මියගියහොත් හෝ ඉල්ලා අස්වුවහොත් පැවැත්වූයේ කුමක්ද?", "අතුරු මැතිවරණයක්", "ජනමත විචාරණයක්", "සමස්ත මහ මැතිවරණයක්", "පළාත් පාලන ඡන්දයක්", "කේවල ක්‍රමයේදී පුරප්පාඩු වන එක් කොට්ඨාසයක් සඳහා පමණක් අතුරු මැතිවරණයක් (By-election) පැවැත්විණි."),
    q("1931 ඩොනමෝර් කොමිසම ශ්‍රී ලංකාවට සර්වජන ඡන්ද බලය නිර්දේශ කිරීමට හේතු වූ ප්‍රධාන කරුණ කුමක්ද?", "සාමාන්‍ය ජනතාවගේ දේශපාලන අවබෝධය හා ජීවන තත්ත්වය නැංවීම", "බ්‍රිතාන්‍ය පාලනය අවසන් කර වහාම පිටව යාම", "රජයේ බදු ආදායම අඩු කර ගැනීම", "කාන්තාවන්ට පමණක් ඡන්ද අයිතිය දීම", "ජනතාවගේ අයිතිවාසිකම් රැකීමට හා සමාජ ප්‍රතිසංස්කරණ ඉදිරියට ගෙන යාමට සර්වජන ඡන්දය යෝග්‍ය විය."),
    q("1947 සිට 1978 දක්වා කාලයේ පැවති සරල බහුතර ක්‍රමයේදී ආසන සීමා නිර්ණය කිරීම සඳහා ප්‍රධාන වශයෙන් සැලකිල්ලට ගත්තේ මොනවාද?", "ජනගහනය සහ වර්ග සැතපුම් ප්‍රමාණය", "රෝහල් ගණන සහ මාර්ග දිග", "වාර්ෂික අපනයන ආදායම", "උපාධිධාරීන්ගේ සංඛ්‍යාව", "අඩු ජනගහනයක් ඇති ග්‍රාමීය ප්‍රදේශවලටද සාධාරණ නියෝජනයක් ලැබෙන සේ භූමි ප්‍රමාණයද සැලකිල්ලට ගැණිනි."),
    q("තනි මාරු ඡන්ද ක්‍රමය (Single Transferable Vote - STV) ප්‍රධාන වශයෙන් භාවිත කරන රටක් කුමක්ද?", "අයර්ලන්තය", "චීනය", "සෞදි අරාබිය", "රුසියාව", "බහු මන්ත්‍රී ආසනවලදී ඡන්දදායකයන් අපේක්ෂකයන් අංකනය කරන STV ක්‍රමය අයර්ලන්තයේ භාවිත වේ."),
    q("පක්ෂය ලැබූ මුළු ඡන්ද ප්‍රමාණයෙන් ප්‍රතිශතය අඩු වුවද සමානුපාතික ක්‍රමයෙන් 'ඡන්ද හා ආසන අතර විශාල පරතරය' අවම කරන්නේ කෙසේද?", "ඡන්ද අනුපාතයට සමානුපාතිකව ආසන බෙදීමෙන්", "සුළු පක්ෂ තහනම් කිරීමෙන්", "ඡන්ද පොළවල් අඩු කිරීමෙන්", "ඇප මුදල් අහෝසි කිරීමෙන්", "5%ට වැඩි සියලු පක්ෂවලට ඔවුන් ලැබූ ඡන්ද අනුපාතයට සමීපව ආසන ප්‍රමාණය හිමිවීම මෙහි ලක්ෂණයකි."),
    q("ශ්‍රී ලංකාවේ ඡන්ද පොළකදී ඡන්දදායකයෙකුගේ අනන්‍යතාව තහවුරු කිරීම සඳහා ඉදිරිපත් කළ යුතු ප්‍රධාන ලියවිල්ල කුමක්ද?", "වලංගු ජාතික හැඳුනුම්පත හෝ පිළිගත් හැඳුනුම්පත", "බැංකු පොත", "විදුලි බිල්පත", "උප්පැන්න සහතිකය", "හොර ඡන්ද වැළැක්වීම සඳහා ජාතික හැඳුනුම්පත, විදේශ ගමන් බලපත්‍රය හෝ රියදුරු බලපත්‍රය අනිවාර්ය වේ."),
    q("ඡන්දදායකයෙකු දෙවන වරටත් ඡන්දය දීම වැළැක්වීම සඳහා ඡන්ද පොළේදී අනුගමනය කරන ක්‍රමවේදය කුමක්ද?", "වම් අතේ සුළැඟිල්ලේ නොමැකෙන තීන්ත ආලේප කිරීම", "අත්සන් දෙකක් ලබාගැනීම", "ඡායාරූපයක් ගැනීම", "ඇඟිලි සලකුණු මුද්‍රණය කිරීම", "වම් අතේ සුළැඟිල්ලේ නියපොත්ත අසල නොමැකෙන තීන්ත ගැල්වීමෙන් ද්විත්ව ඡන්ද ප්‍රකාශනය වළක්වයි."),
    q("කිසියම් මැතිවරණයකට පෙරාතුව අපේක්ෂකයන්ගේ වියදම් සීමා කිරීමට ශ්‍රී ලංකාව 2023 දී සම්මත කළ නව නීතිය කුමක්ද?", "මැතිවරණ වියදම් නියාමන පනත", "තොරතුරු දැනගැනීමේ පනත", "දූෂණ විරෝධී පනත", "පළාත් පාලන විශේෂ විධිවිධාන පනත", "2023 අංක 3 දරන මැතිවරණ වියදම් නියාමන පනතින් අපේක්ෂක ප්‍රචාරණ වියදම්වලට නීතිමය සීමා පැනවුණි."),
    q("ශ්‍රී ලංකාවේ පාර්ලිමේන්තු මැතිවරණයකට තරග කළ හැකි පුරවැසියෙකුගේ අවම වයස් සීමාව කුමක්ද?", "අවුරුදු 18", "අවුරුදු 21", "අවුරුදු 25", "අවුරුදු 30", "1978 ව්‍යවස්ථාව අනුව ඡන්ද බලය හිමි අවුරුදු 18 සම්පූර්ණ ඕනෑම සුදුසුකම් ලත් පුරවැසියෙකුට තරග කළ හැක."),
    q("සමානුපාතික නියෝජන ක්‍රමයේදී 'කැපී පෙනෙන ජාතික ප්‍රශ්නවලට වඩා පෞද්ගලික මනාප තරගයට ප්‍රමුඛතාව ලැබීම' යනු කුමක්ද?", "මැතිවරණ ක්‍රමයේ දුර්වලතාවකි", "ව්‍යවස්ථාදායකයේ වරප්‍රසාදයකි", "සෘජු ප්‍රජාතන්ත්‍රවාදී ලක්ෂණයකි", "අධිකරණ ස්වාධීනත්වයේ අංගයකි", "පක්ෂ ප්‍රතිපත්ති අභිබවා අපේක්ෂකයන් පෞද්ගලික මනාප අංක ප්‍රවර්ධනය කිරීමට යොමු වීම විවේචනයට ලක්වේ."),
    q("ශ්‍රී ලංකාවේ පළාත් පාලන මැතිවරණ සඳහා කාන්තා නියෝජනය අනිවාර්ය කිරීමෙන් ලැබෙන අවම ප්‍රතිශතය කීයද?", "25%", "10%", "50%", "5%", "සංශෝධිත පළාත් පාලන මැතිවරණ නීතිය අනුව සභික ධුරවලින් අවම වශයෙන් 25%ක් කාන්තාවන්ට වෙන් කර ඇත."),
    q("ඡන්ද පෙට්ටියේ ආරක්ෂාව තහවුරු කිරීම සඳහා ඡන්ද විමසීම ආරම්භයේදී ඡන්ද ස්ථානාධිපතිවරයා කුමක් කළ යුතුද?", "පෙට්ටිය හිස් බව පෙන්වා නියෝජිතයන් ඉදිරියේ මුද්‍රා තැබීම", "පෙට්ටිය පොලිසියට භාර දීම", "ඡන්ද පත්‍රිකා 100ක් කලින් දැමීම", "දිස්ත්‍රික් ලේකම් කාර්යාලයට යැවීම", "පක්ෂ නියෝජිතයන් ඉදිරියේ හිස් ඡන්ද පෙට්ටිය පරීක්ෂා කරවා ආරක්ෂිතව මුද්‍රා තැබීම අනිවාර්ය වේ."),
    q("රහස් ඡන්දයෙන් ඡන්දදායකයාට හිමිවන ප්‍රධානතම ආරක්ෂාව කුමක්ද?", "අන් අයගේ බලපෑමෙන් හා පළිගැනීමෙන් මිදී තීරණය ගැනීම", "නිවසේ සිට ඡන්දය තැපැල් කිරීම", "අපේක්ෂකයන්ගෙන් මුදල් ලබාගැනීම", "ඡන්ද පොළේදී ප්‍රසිද්ධියේ කතා කිරීම", "තමන් කාට ඡන්දය දුන්නේද යන්න රහසක්ව පවතින බැවින් පළිගැනීම් හා තර්ජනවලින් ආරක්ෂා වේ."),
    q("සමානුපාතික නියෝජනය යටතේ 'කොට්ඨාසයකට සෘජුව වගකියන මන්ත්‍රීවරයෙකු නොමැති වීම' ඇතිවන්නේ ඇයි?", "මන්ත්‍රීවරුන් සියල්ල දිස්ත්‍රික් මට්ටමින් තේරී පත්වන බැවිනි", "පාර්ලිමේන්තුවේ මන්ත්‍රීවරුන් අඩු බැවිනි", "ඡන්ද පත්‍රිකාවේ නම් නොමැති බැවිනි", "ජනාධිපති සියලු මන්ත්‍රීන් පත් කරන බැවිනි", "තනි කොට්ඨාස නියෝජිතයන් නොමැතිව මුළු දිස්ත්‍රික්කයටම මන්ත්‍රීවරුන් කිහිප දෙනෙකු පත්වීම මෙයට හේතුවයි."),
    q("අතීතයේ සර්වජන ඡන්ද බලය ලැබීමට පෙර කාන්තාවන්ට ඡන්ද අයිතිය දිනාගැනීමේ ව්‍යාපාරය හැඳින්වූයේ කුමන නමින්ද?", "සෆ්‍රජෙට් ව්‍යාපාරය", "ප්‍රතිසංස්කරණ ව්‍යාපාරය", "කම්කරු සමිති ව්‍යාපාරය", "නොබැඳි ව්‍යාපාරය", "බ්‍රිතාන්‍යයේ හා බටහිර රටවල කාන්තා ඡන්ද අයිතිය වෙනුවෙන් සටන් කළ සංවිධාන සෆ්‍රජෙට් (Suffragette) නම් විය."),
    q("ශ්‍රී ලංකාවේ රාජ්‍ය මන්ත්‍රණ සභාවට තේරී පත් වූ ප්‍රථම කාන්තා මන්ත්‍රීවරිය කවුද?", "ඇඩ්ලින් මොලමුරේ", "සිරිමාවෝ බණ්ඩාරනායක", "විමලා විජයවර්ධන", "චන්ද්‍රිකා බණ්ඩාරනායක", "1931 දී රුවන්වැල්ල අතුරු මැතිවරණයෙන් ඇඩ්ලින් මොලමුරේ ප්‍රථම කාන්තා නියෝජිතවරිය ලෙස තේරී පත්විය."),
    q("1978 ව්‍යවස්ථාව යටතේ පළමු වරට සමානුපාතික නියෝජන ක්‍රමය අනුව පාර්ලිමේන්තු මැතිවරණයක් පැවැත්වූයේ කුමන වර්ෂයේදීද?", "1989", "1977", "1982", "1994", "1977 මහ මැතිවරණය කේවල ක්‍රමයෙන් පැවැති අතර 1989 පෙබරවාරි මැතිවරණය පළමු සමානුපාතික මහ මැතිවරණය විය."),
    q("මැතිවරණයකදී කිසියම් අපේක්ෂකයෙකු මියගියහොත් හෝ ඉවත් වුවහොත් ජයග්‍රාහකයාගේ බහුතරය කෙරෙහි බලපාන දත්තය කුමක්ද?", "ප්‍රකාශිත වලංගු ඡන්ද සංඛ්‍යාව", "මුළු ජනගහනය", "ප්‍රතික්ෂේපිත ඡන්ද සංඛ්‍යාව", "ඇප මුදල් වටිනාකම", "ඕනෑම මැතිවරණ ප්‍රතිඵලයක් ගණනය කරනු ලබන්නේ ප්‍රකාශිත මුළු වලංගු ඡන්ද සංඛ්‍යාව පදනම් කරගෙනය."),
    q("සරල බහුතර ක්‍රමයේදී 'ශක්තිමත් ස්ථාවර ආණ්ඩුවක් බිහිවීමේ ඉඩකඩ වැඩිවීම' සිදුවන්නේ කෙසේද?", "වැඩිම ඡන්ද ගන්නා පක්ෂයට පැහැදිලි ආසන බහුතරයක් ලැබීමෙන්", "සෑම පක්ෂයකටම ආසන 5 බැගින් ලැබීමෙන්", "මැතිවරණ අවලංගු කිරීමෙන්", "ඇමතිවරුන් සංඛ්‍යාව සීමා නොවීමෙන්", "සුළු ඡන්ද වැඩිවීමකින් පවා ආසන රැසක් ජයගත හැකි බැවින් එක් පක්ෂයකට ස්ථාවර බහුතරයක් ලැබේ."),
    q("ඡන්දදායකයන් වෙත නිකුත් කරන 'නිල ඡන්ද දැන්වීම් පත්‍රිකාව' (Polling Card) ලබාදීමේ අරමුණ කුමක්ද?", "ඡන්දදායකයාගේ ඡන්ද මධ්‍යස්ථානය හා ලියාපදිංචි අංකය දැනුම් දීම", "ජාතික හැඳුනුම්පත වෙනුවට ආදේශකයක් ලෙස භාවිත කිරීම", "ඡන්ද පත්‍රිකාව වෙනුවට පෙට්ටියට දැමීම", "රජයේ බදු නිදහසක් ලබාගැනීම", "තමන් ලියාපදිංචි ඡන්ද පොළ හා අනුක්‍රමික අංකය පහසුවෙන් දැනගැනීමට තැපෑලෙන් නිල ඡන්ද දැන්වීම් පත්‍රිකා බෙදා හැරේ."),
    q("මැතිවරණයකට නාමයෝජනා භාරගත් පසු පක්ෂයකට හෝ කණ්ඩායමකට අපේක්ෂක නාමලේඛනය හිතුමතේ වෙනස් කළ හැකිද?", "නැත, නීතිමය කාලයෙන් පසු වෙනස් කළ නොහැක", "ඔව්, ඡන්ද දිනයේ උදෑසන දක්වා වෙනස් කළ හැක", "ඔව්, පළාත් ආණ්ඩුකාරවරයාගේ කැමැත්තෙන් වෙනස් කළ හැක", "ඔව්, පොලිස්පතිවරයාගේ අවසරයෙන් වෙනස් කළ හැක", "නාමයෝජනා භාරගෙන පිළිගැනීමෙන් පසු නීතිමය හේතුවක් නොමැතිව අපේක්ෂක නම් වෙනස් කළ නොහැක."),
    q("දිස්ත්‍රික්කයක ලියාපදිංචි ඡන්දදායකයන් සංඛ්‍යාව සහිත ඡන්ද හිමි නාමලේඛනය සෑම වසරකම සංශෝධනය කරන්නේ ඇයි?", "වයස 18 සපිරුණු නව ඡන්දදායකයන් ඇතුළත් කිරීමට හා මියගිය අය ඉවත් කිරීමට", "මැතිවරණ කොට්ඨාස සංඛ්‍යාව අඩු කිරීමට", "පක්ෂ ලාංඡන වෙනස් කිරීමට", "අග්‍රාමාත්‍ය ධුර කාලය දීර්ඝ කිරීමට", "නව වැඩිහිටියන් එක් කිරීමට, මියගිය අය හා පදිංචිය මාරු කළ අය යාවත්කාලීන කිරීමට වාර්ෂික ප්‍රතිශෝධනය අවශ්‍ය වේ."),
    q("ප්‍රජාතන්ත්‍රවාදී මැතිවරණයකදී ඡන්දදායකයන් අතර 'ඡන්ද අල්ලස්' (Bribery) ලබාදීම නීතියෙන් තහනම් කර ඇත්තේ ඇයි?", "ඡන්දදායකයාගේ නිදහස් හා ස්වාධීන තීරණය විකෘති වන බැවිනි", "මැතිවරණ දිනයේ බැංකු වසා ඇති බැවිනි", "තැපැල් ඡන්ද පමණක් ගණන් කරන බැවිනි", "ජාතික ලැයිස්තුව අහෝසි වන බැවිනි", "මුදල් හෝ ද්‍රව්‍යමය තෑගි දී ඡන්දය ලබාගැනීම මැතිවරණ දූෂණයක් වන අතර නිදහස් තේරීමට බාධා කරයි."),
    q("ශ්‍රී ලංකාවේ ප්‍රාදේශීය හෝ පාර්ලිමේන්තු මැතිවරණයකදී ඡන්ද පත්‍රිකාවක කතිරය ගැසිය යුත්තේ කුමන ස්ථානයේද?", "තෝරාගත් පක්ෂයේ නම හා ලකුණ ඉදිරියේ ඇති හිස් කොටුව තුළ", "අපේක්ෂකයාගේ නම මත", "ඡන්ද පත්‍රිකාවේ පිටුපස පැත්තේ", "මැතිවරණ කොමිසමේ මුද්‍රාව මත", "පක්ෂයේ නම හා සලකුණ ඉදිරියේ ඇති නිශ්චිත හිස් කොටුව තුළ කතිරය සලකුණු කළ යුතුය."),
    q("පාර්ලිමේන්තු මැතිවරණයේදී ඡන්දදායකයෙකු පක්ෂයකට කතිරය නොගසා මනාප අංකය පමණක් රවුම් කළහොත් එම ඡන්දය කුමක් වේද?", "ප්‍රතික්ෂේපිත ඡන්දයක් බවට පත්වේ", "එම පක්ෂයට වලංගු ඡන්දයක් ලෙස ගැනේ", "ජාතික ලැයිස්තුවට එකතු වේ", "ප්‍රසාද ආසනයට ගණන් ගැනේ", "පළමුව පක්ෂයට වලංගු කතිරය ලකුණු නොකර මනාප පමණක් ලකුණු කළහොත් මුළු ඡන්ද පත්‍රිකාවම අවලංගු වේ."),
    q("සමානුපාතික නියෝජනය යටතේ 'විශාලතම ශේෂ ක්‍රමය' අනුගමනය කිරීමේදී ඉතිරි ආසන ලබාදෙන්නේ කුමන පදනමකින්ද?", "කෝටාව බෙදීමෙන් පසු වැඩිම ඉතිරි ඡන්ද සංඛ්‍යාවක් ඇති පක්ෂවලට", "අඩුම ඡන්ද සංඛ්‍යාවක් ගත් පක්ෂවලට", "කාන්තා අපේක්ෂකයන් වැඩිම පක්ෂවලට", "පැරණිතම දේශපාලන පක්ෂවලට", "කෝටාව අනුව පූර්ණ ආසන දීමෙන් පසු ඉතිරි වන ආසන වැඩිම ඡන්ද ශේෂය ඇති පක්ෂ අනුපිළිවෙළින් බෙදයි."),
    q("සරල බහුතර ක්‍රමයේදී 'පක්ෂයක් රට පුරා වැඩිම ඡන්ද ගත්තත් ආසන ගණන අඩු වීමේ' අසාධාරණය ඇතිවිය හැක්කේ ඇයි?", "ජයග්‍රාහී ඡන්ද ආසන කිහිපයක පමණක් විශාල වශයෙන් ගොනු වීමෙන්", "ජාතික ලැයිස්තුව ක්‍රියාත්මක වීමෙන්", "මනාප තුනක් දීමෙන්", "ජනමත විචාරණය පැවැත්වීමෙන්", "එක් කලාපයක අතිවිශාල වැඩි ඡන්දයෙන් ආසන කිහිපයක් දිනා අනෙක් කොට්ඨාස සුළු ඡන්දයෙන් පැරදීම නිසාය."),
    q("ශ්‍රී ලංකාවේ 5% අවම ඡන්ද සීමාව (Cutoff point) ක්‍රියාත්මක වන්නේ කුමන අවදානම වැළැක්වීම සඳහාද?", "ඉතා කුඩා පක්ෂ විශාල ගණනක් බිහිවී පාර්ලිමේන්තුව අස්ථාවර වීම", "විපක්ෂ නායක ධුරය අහෝසි වීම", "ඡන්දදායක වයස අඩු වීම", "පළාත් සභා බලතල වැඩි වීම", "අතිශය කුඩා පක්ෂ ගණනාවක් අතර ආසන බෙදී ගොස් ස්ථාවර ආණ්ඩුවක් පිහිටුවීම අසීරු වීම වැළැක්වීම මෙහි අරමුණයි."),
    q("ඡන්ද පත්‍රිකාවක 'මම කාටත් කැමති නැත' යනුවෙන් ලිඛිත සටහනක් තැබුවහොත් සිදුවන්නේ කුමක්ද?", "ඡන්ද පත්‍රිකාව ප්‍රතික්ෂේප වේ", "ප්‍රසාද ආසනය අවලංගු වේ", "නව මැතිවරණයක් කැඳවයි", "විපක්ෂයට ඡන්දය එකතු වේ", "වලංගු කතිරයට අමතරව වෙනත් ලේඛන හෝ සලකුණු තැබූ විට එම ඡන්ද පත්‍රිකාව අවලංගු කෙරේ."),
    q("ශ්‍රී ලංකාවේ පළමු පාර්ලිමේන්තු මැතිවරණය පැවැත්වූයේ කුමන වර්ෂයේදීද?", "1947", "1931", "1948", "1956", "සෝල්බරි ව්‍යවස්ථාව යටතේ 1947 අගෝස්තු-සැප්තැම්බර් මාසවල පළමු පාර්ලිමේන්තු මැතිවරණය පැවැත්වුණි."),
    q("නූතන ප්‍රජාතන්ත්‍රවාදයේදී 'ප්‍රාථමික මැතිවරණ' (Primary Elections) ප්‍රධාන වශයෙන් පවත්වනු ලබන්නේ කුමක් සඳහාද?", "පක්ෂයක නිල අපේක්ෂකයා පක්ෂ සාමාජික ඡන්දයෙන් තේරීමට", "රටේ ජනාධිපතිවරයා අවසන් වශයෙන් පත් කිරීමට", "අධිකරණ විනිසුරුවරුන් පත් කිරීමට", "පළාත් ආණ්ඩුකාරවරයා ඉවත් කිරීමට", "ඇමරිකා එක්සත් ජනපදය වැනි රටවල පක්ෂ අපේක්ෂකයන් තේරීමට ප්‍රාථමික මැතිවරණ පැවැත්වේ."),
    q("සෘජු ඡන්දයෙන් නොව පළාත් පාලන හෝ ප්‍රාන්ත නියෝජිතයන් මඟින් නියෝජිතයන් පත්කරන ක්‍රමය හැඳින්වෙන්නේ කෙසේද?", "වක්‍ර මැතිවරණ ක්‍රමය", "සෘජු මැතිවරණ ක්‍රමය", "සර්වජන මනාප ක්‍රමය", "විවෘත ජනමත විචාරණය", "මහජනතාව තෝරාගත් නියෝජිත මණ්ඩලයක් මඟින් තවත් නිලධාරියෙකු හෝ සභාවක් පත් කිරීම වක්‍ර මැතිවරණයකි."),
    q("ශ්‍රී ලංකාවේ විධායක ජනාධිපති ධුරය සඳහා පළමු වරට වක්‍ර මැතිවරණයක් නොව පාර්ලිමේන්තුව මඟින් ජනාධිපතිවරයෙකු පත් කළ හැක්කේ කවර අවස්ථාවකද?", "ජනාධිපති ධුර කාලය අවසන් වීමට පෙර ධුරය හිස් වූ විට", "සෑම වසර පහකටම වරක්", "පළාත් සභා විසුරුවා හරින සෑම විටම", "අග්‍රාමාත්‍යවරයා විදේශගත වූ විට", "ධුර කාලය මැදදී ජනාධිපති ධුරය හිස් වූ විට ඉතිරි කාලය සඳහා පාර්ලිමේන්තුවෙන් රහස් ඡන්දයෙන් අනුප්‍රාප්තික ජනාධිපතිවරයෙකු තෝරයි."),
    q("1978 ව්‍යවස්ථාවේ සමානුපාතික නියෝජන ක්‍රමය තුළ දිස්ත්‍රික්කයක අවම මන්ත්‍රී ආසන සංඛ්‍යාව තීරණය වීමේදී බස්නාහිර පළාතේ වැඩිම ආසන ඇති දිස්ත්‍රික්කය කුමක්ද?", "කොළඹ සහ ගම්පහ", "කළුතර සහ රත්නපුර", "ගාල්ල සහ මාතර", "මහනුවර සහ කුරුණෑගල", "වැඩිම ඡන්දදායක ජනගහනයක් සිටින කොළඹ සහ ගම්පහ දිස්ත්‍රික්කවලට වැඩිම පාර්ලිමේන්තු ආසන හිමිවේ."),
    q("සෑම මැතිවරණ දිස්ත්‍රික්කයකම පක්ෂයක් ඉදිරිපත් කරන නාමයෝජනා පත්‍රයේ ඇතුළත් විය යුතු මුළු අපේක්ෂක සංඛ්‍යාව කුමක්ද?", "දිස්ත්‍රික්කයට හිමි ආසන ගණනට අමතරව අතිරේක 3ක්", "දිස්ත්‍රික්කයට හිමි ආසන ගණනින් අඩක්", "සෑම දිස්ත්‍රික්කයටම 50 බැගින්", "එක් අපේක්ෂකයෙකු පමණක්", "නීතිය අනුව දිස්ත්‍රික්කයෙන් තෝරා ගන්නා ආසන සංඛ්‍යාවට තවත් අපේක්ෂකයන් තිදෙනෙකු එකතු කර නාමයෝජනා දිය යුතුය.")
  )
}
